    'chapter' => 'block',
    'sourceId' => 'av-block-1',
    'stem' => '按本站《一度房室传导阻滞》课程，以下哪项是定义？',
    'options' => 
    array (
      0 => '窦性心动过速是窦房结发放冲动频率超过 100 次/分的状态，P 波形态仍为窦性且与 QRS 一一对应。',
      1 => '正常窦性心律指冲动由窦房结发出，按固定顺序经心房、房室结、希氏束-浦肯野系统下传，形成形态一致的 P 波与窄 QRS 波群。',
      2 => '窦性心动过缓是窦房结发放冲动的频率低于 60 次/分，P 波形态与房室传导顺序仍属正常；生理性多见于运动员与睡眠状态，病理性可见于药物抑制、甲状腺功能减退、缺血或病态窦房结综合征。',
      3 => '一度房室传导阻滞是房室传导延迟，使 PR 间期恒定超过 0.20 s，但每个心房冲动仍能下传心室，没有 QRS 脱漏。它反映房室传导时间延长而非传导中断，可见于迷走张力增高、药物、缺血、心肌炎或传导系统退行性变。',
    ),
    'answerIndex' => 3,
    'explanation' => '《一度房室传导阻滞》的定义：一度房室传导阻滞是房室传导延迟，使 PR 间期恒定超过 0.20 s，但每个心房冲动仍能下传心室，没有 QRS 脱漏。它反映房室传导时间延长而非传导中断，可见于迷走张力增高、药物、缺血、心肌炎或传导系统退行性变。',
    'difficulty' => 1,
  ),
